import React, { useEffect, useState } from "react";
import AdminProtectedRoute from "../components/adminProtectedRoute";
import { auth } from "../../firebaseConfig";
import { signOut } from "firebase/auth";
import { graphql, navigate } from "gatsby";
import { collection, getDocs, QueryDocumentSnapshot, deleteDoc, doc } from "firebase/firestore";
import { db } from "../../firebaseConfig";
import { useTranslation } from "gatsby-plugin-react-i18next";


type ContactRecord = {
  id: string;
  name?: string;
  email?: string;
  phone?: string;
  message?: string;
  createdAt?: { seconds: number; nanoseconds: number };
};

type TableColumn = {
  key: string;
  label: string;
};

type TableRow = Record<string, React.ReactNode>;

type RecordsTableProps = {
  title: string;
  loadingText: string;
  emptyText: string;
  errorText: string;
  columns: TableColumn[];
  rows: TableRow[];
  isLoading: boolean;
  hasError: boolean;
  currentPage: number;
  totalPages: number;
  onPageChange: (page: number) => void;
  paginationText: string;
  previousLabel: string;
  nextLabel: string;
};

const RecordsTable = ({
  title,
  loadingText,
  emptyText,
  errorText,
  columns,
  rows,
  isLoading,
  hasError,
  currentPage,
  totalPages,
  onPageChange,
  paginationText,
  previousLabel,
  nextLabel,
}: RecordsTableProps) => {


  return (

    <div className="mb-10">
      <div className="mb-4 text-sm font-semibold">{title}</div>

      {isLoading && (
        <div className="text-sm text-DarkGrayText">{loadingText}</div>
      )}
      {!isLoading && hasError && (
        <div className="text-sm text-Red">{errorText}</div>
      )}
      {!isLoading && !hasError && rows.length === 0 && (
        <div className="text-sm text-DarkGrayText">{emptyText}</div>
      )}

      {!isLoading && !hasError && rows.length > 0 && (
        <>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm border-collapse">
              <thead>
                <tr className="border-b border-LightGrayText">
                  {columns.map((column) => (
                    <th key={column.key} className="py-2 pr-3">
                      {column.label}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {rows.map((row, index) => (
                  <tr key={index} className="border-b border-LightGrayText/20">
                    {columns.map((column) => (
                      <td key={column.key} className="py-2 pr-3">
                        {row[column.key] || "-"}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {totalPages > 1 && (
            <div className="mt-4 flex items-center justify-end gap-3 text-sm">
              <span className="text-DarkGrayText">{paginationText}</span>
              <button
                type="button"
                onClick={() => onPageChange(Math.max(1, currentPage - 1))}
                className="rounded-md border border-LightGrayText px-3 py-1 text-DarkGreen hover:border-Yellow disabled:opacity-40"
                disabled={currentPage === 1}
              >
                {previousLabel}
              </button>
              <button
                type="button"
                onClick={() => onPageChange(Math.min(totalPages, currentPage + 1))}
                className="rounded-md border border-LightGrayText px-3 py-1 text-DarkGreen hover:border-Yellow disabled:opacity-40"
                disabled={currentPage === totalPages}
              >
                {nextLabel}
              </button>
            </div>
          )}
        </>
      )}
    </div>

  );
};

const AdminPage = () => {
  const { t } = useTranslation();
  const pageSize = 10;
  const [contactRecords, setContactRecords] = useState<ContactRecord[]>([]);
  const [loadingContactRecords, setLoadingContactRecords] = useState(true);
  const [contactRecordsError, setContactRecordsError] = useState("");
  const [contactPage, setContactPage] = useState(1);
  const [pendingDeleteId, setPendingDeleteId] = useState<string | null>(null);

  useEffect(() => {
    const fetchContactRecords = async () => {
      try {
        const snapshot = await getDocs(collection(db, "contactMessages"));
        const rows = snapshot.docs.map((doc: QueryDocumentSnapshot) => ({
          id: doc.id,
          ...(doc.data() as Omit<ContactRecord, "id">),
        }));
        setContactRecords(rows);
      } catch (error) {
        console.error("Error loading contact records:", error);
        setContactRecordsError(
          t("admin.errors.loadContactRecords") || "Unable to load records."
        );
      } finally {
        setLoadingContactRecords(false);
      }
    };

    fetchContactRecords();
  }, [t]);

  const formatDate = (createdAt?: { seconds: number; nanoseconds: number }) => {
    if (!createdAt?.seconds) return "-";
    const date = new Date(createdAt.seconds * 1000);
    return date.toLocaleString("en-US", {
      month: "long",
      day: "numeric",
      year: "numeric",
      hour: "numeric",
      minute: "2-digit",
      hour12: true,
    });
  };

  const createdAtSeconds = (
    createdAt?: { seconds: number; nanoseconds: number }
  ) => createdAt?.seconds || 0;

  const paginateRows = (rows: TableRow[], page: number) => {
    const start = (page - 1) * pageSize;
    return rows.slice(start, start + pageSize);
  };

  const handleLogout = async () => {
    await signOut(auth);
    navigate("/login");
  };

  const handleDeleteContact = async (id: string) => {
    try {
      await deleteDoc(doc(db, "contactMessages", id));
      setContactRecords((prev) => prev.filter((record) => record.id !== id));
    } catch (error) {
      console.error("Error deleting contact message:", error);
      setContactRecordsError(
        t("admin.errors.deleteContactRecord") || "Unable to delete record."
      );
    }
  };

  const contactColumns: TableColumn[] = [
    {
      key: "name",
      label: t("admin.contactMessages.columns.name") || "Name",
    },
    {
      key: "email",
      label: t("admin.contactMessages.columns.email") || "Email",
    },
    {
      key: "phone",
      label: t("admin.contactMessages.columns.phone") || "Phone",
    },
    {
      key: "message",
      label: t("admin.contactMessages.columns.message") || "Message",
    },
    {
      key: "createdAt",
      label: t("admin.contactMessages.columns.createdAt") || "Created At",
    },
    {
      key: "actions",
      label: t("admin.contactMessages.columns.actions") || "Actions",
    },
  ];

  const sortedContacts = [...contactRecords].sort(
    (a, b) => createdAtSeconds(b.createdAt) - createdAtSeconds(a.createdAt)
  );

  const contactRows: TableRow[] = sortedContacts.map((record) => ({
    name: record.name || "-",
    email: record.email || "-",
    phone: record.phone || "-",
    message: record.message || "-",
    createdAt: formatDate(record.createdAt),
    actions: (
      <button
        type="button"
        onClick={() => {
          setPendingDeleteId(record.id);
        }}
        className="inline-flex items-center justify-center rounded-md border border-LightGrayText px-2 py-1 text-DarkGreen hover:border-Red hover:text-Red"
        aria-label={t("admin.contactMessages.actions.remove") || "Remove"}
        title={t("admin.contactMessages.actions.remove") || "Remove"}
      >
        <svg
          viewBox="0 0 24 24"
          width="16"
          height="16"
          aria-hidden="true"
          className="fill-current"
        >
          <path d="M9 3h6l1 2h4v2H4V5h4l1-2zm1 6h2v9h-2V9zm4 0h2v9h-2V9zM7 9h2v9H7V9z" />
        </svg>
      </button>
    ),
  }));

  const contactTotalPages = Math.max(
    1,
    Math.ceil(contactRows.length / pageSize)
  );
  const contactPageRows = paginateRows(contactRows, contactPage);

  useEffect(() => {
    setContactPage((page) => Math.min(page, contactTotalPages));
  }, [contactTotalPages]);

  return (
    <AdminProtectedRoute>
      <div className="min-h-screen bg-DarkGreen py-10">
        <div className="max-w-6xl mx-auto px-4">
          <div className="bg-MidGray p-6 rounded-lg shadow-md border border-LightGrayText text-DarkGreen">
            <div className="flex items-center justify-between mb-6">
              <div className="text-lg font-semibold">
                {t("admin.title") || "Admin"}
              </div>
              <button
                type="button"
                onClick={handleLogout}
                className="border body-mob sm:body !backdrop-blur-md rounded-lg py-2 px-4 border-LightGrayText hover:border-Yellow bg-white/10 hover:bg-white/20 active:bg-Yellow active:border-LightGrayText active:text-DarkGreen"
              >
                {t("admin.logout") || "Logout"}
              </button>
            </div>
            <RecordsTable
              title={t("admin.contactMessages.title") || "Contact Messages"}
              loadingText={
                t("admin.contactMessages.loading") || "Loading records..."
              }
              emptyText={t("admin.contactMessages.empty") || "No records yet."}
              errorText={contactRecordsError}
              columns={contactColumns}
              rows={contactPageRows}
              isLoading={loadingContactRecords}
              hasError={!!contactRecordsError}
              currentPage={contactPage}
              totalPages={contactTotalPages}
              onPageChange={setContactPage}
              paginationText={
                t("admin.pagination.pageOf", {
                  current: contactPage,
                  total: contactTotalPages,
                }) || `Page ${contactPage} of ${contactTotalPages}`
              }
              previousLabel={t("admin.pagination.previous") || "Previous"}
              nextLabel={t("admin.pagination.next") || "Next"}
            />
          </div>
        </div>
      </div>
      {pendingDeleteId && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50">
          <div className="w-full max-w-md rounded-lg border border-LightGrayText bg-MidGray p-6 text-DarkGreen shadow-md">
            <div className="mb-2 text-lg font-semibold">
              {t("admin.contactMessages.confirm.title") || "Confirm deletion"}
            </div>
            <div className="mb-6 text-sm text-DarkGrayText">
              {t("admin.contactMessages.confirm.body") ||
                "This action cannot be undone."}
            </div>
            <div className="flex items-center justify-end gap-3">
              <button
                type="button"
                onClick={() => {
                  setPendingDeleteId(null);
                }}
                className="rounded-md border border-LightGrayText px-4 py-2 text-DarkGreen hover:border-Yellow"
              >
                {t("admin.contactMessages.confirm.cancel") || "Cancel"}
              </button>
              <button
                type="button"
                onClick={() => {
                  const id = pendingDeleteId;
                  setPendingDeleteId(null);
                  handleDeleteContact(id);
                }}
                className="rounded-md border border-Red bg-Red/10 px-4 py-2 text-Red hover:bg-Red/20"
              >
                {t("admin.contactMessages.confirm.confirm") || "Delete"}
              </button>
            </div>
          </div>
        </div>
      )}
    </AdminProtectedRoute>
  );
};

export default AdminPage;

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;
